document.addEventListener('alpine:init',()=>Alpine.data('libraryWorkspace',()=>({
 theme:new URLSearchParams(location.search).get('theme')||'purple', mode:'info', directory:'services', query:'', tagIds:[], selected:null, descendants:true, reverse:false, collapsed:[], notice:'', surface:'', error:'', menu:null, menuPosition:'', draftName:'',draftParent:null,editId:null,directorySearch:'',draftTags:[],tagSearch:'',editTag:undefined,tagNameDraft:'',pendingTag:null,failNext:false,
 titles:{create:'新建目录',rename:'重命名目录',move:'移动目录',delete:'删除目录',tags:'管理标签',filter:'筛选标签',organize:'调整目录与标签',deleteTag:'删除标签',newInfo:'新建信息'},
 dirs:[{id:'work',name:'工作',parent:null},{id:'beichen',name:'北辰项目',parent:'work'},{id:'services',name:'服务',parent:'beichen'},{id:'project',name:'项目资料',parent:'beichen'},{id:'test',name:'测试环境',parent:'work'},{id:'personal',name:'个人',parent:null}],
 tags:[{id:'document',name:'文档'},{id:'team',name:'协作'},{id:'testenv',name:'测试环境'},{id:'linux',name:'Linux'},{id:'pending',name:'待迁移'}],
 items:[{id:'docs',name:'文档服务',description:'北辰项目的文档入口与部署位置。',directory:'services',tags:['document','team'],fields:[{name:'访问地址',value:'https://docs.beichen.example'},{name:'部署目录',value:'/srv/beichen/docs'}]},{id:'server',name:'北辰测试服务器',description:'用于联调和部署验证的服务器。',directory:'services',tags:['testenv','linux'],fields:[{name:'服务器地址',value:'test.beichen.example'},{name:'登录用户',value:'developer'}]},{id:'agreement',name:'项目约定',description:'项目协作使用的基本约定。',directory:'project',tags:['team'],fields:[{name:'项目代号',value:'BEICHEN'}]},{id:'resume',name:'个人简历',description:'求职时使用的简历文件。',directory:null,tags:['document'],file:true,fields:[{name:'简历附件',value:'个人简历.pdf · 128 KB'}]}],
 init(){const p=new URLSearchParams(location.search),state=p.get('state');if(!state){try{const saved=JSON.parse(localStorage.getItem('agent-info-library-prototype-v6'));if(saved&&Array.isArray(saved.dirs)&&Array.isArray(saved.tags)&&Array.isArray(saved.items)){this.dirs=saved.dirs;this.tags=saved.tags;this.items=saved.items;if(!this.dirs.some(d=>d.id===this.directory))this.directory=null;}}catch{}}if(state==='stress'){for(let i=0;i<50;i++)this.dirs.push({id:'d'+i,name:i===5?'很长的项目目录名称用于检查省略与按钮避让':'项目 '+String(i+1).padStart(2,'0'),parent:i===0?'services':i<4?'d'+(i-1):'work'});for(let i=5;i<100;i++)this.tags.push({id:'t'+i,name:'标签 '+(i+1)});for(let i=4;i<200;i++)this.items.push({id:'i'+i,name:'项目信息 '+String(i).padStart(3,'0'),description:'项目日常维护信息。',directory:'d'+(i%50),tags:['t'+(i%95+5)],fields:[{name:'地址',value:'https://service.example'}]});this.directory=null;}if(state==='empty'){this.dirs=[];this.items=[];this.tags=[];this.directory=null;}if(['create','move','tags','organize','error'].includes(state))queueMicrotask(()=>{if(state==='tags')this.open('tags');else if(state==='organize')this.organize();else{this.editDirectory(state==='move'?'services':null,'beichen');if(state==='error')this.failNext=true;}});},
 tree(all=false,parent=null,depth=0,seen=[]){return this.dirs.filter(d=>d.parent===parent&&!seen.includes(d.id)).flatMap(d=>[{...d,depth},...((all||!this.collapsed.includes(d.id))?this.tree(all,d.id,depth+1,[...seen,d.id]):[])]);},
 hasChildren(id){return this.dirs.some(d=>d.parent===id);},toggle(id){this.collapsed=this.collapsed.includes(id)?this.collapsed.filter(v=>v!==id):[...this.collapsed,id];},
 descendantsOf(id){const ids=new Set([id]);for(let n=0;n<this.dirs.length;n++)for(const d of this.dirs)if(ids.has(d.parent))ids.add(d.id);return ids;},count(id){return this.items.filter(i=>this.descendantsOf(id).has(i.directory)).length;},
 path(id){if(!id)return '未分类';const names=[],seen=new Set();while(id&&!seen.has(id)){seen.add(id);const d=this.dirs.find(d=>d.id===id);if(!d)break;names.unshift(d.name);id=d.parent;}return names.join(' / ')||'未分类';},scopeName(){return this.directory==='none'?'未分类':this.dirs.find(d=>d.id===this.directory)?.name||'全部信息';},tagName(id){return this.tags.find(t=>t.id===id)?.name||'';},
 filtered(){const ids=this.directory&&this.directory!=='none'?(this.descendants?this.descendantsOf(this.directory):new Set([this.directory])):null;const rows=this.items.filter(i=>(this.directory!=='none'||!i.directory)&&(!ids||ids.has(i.directory))&&i.name.toLowerCase().includes(this.query.toLowerCase())&&this.tagIds.every(t=>i.tags.includes(t))).sort((a,b)=>a.name.localeCompare(b.name,'zh'));return this.reverse?rows.reverse():rows;},current(){return this.filtered().find(i=>i.id===this.selected)||this.filtered()[0]||null;},choose(id){this.directory=id;this.selected=null;},all(){this.directory=null;this.query='';this.tagIds=[];this.selected=null;},
 open(name){this.surface=name;this.error='';this.menu=null;this.opener=document.activeElement;if(name==='filter')this.draftTags=[...this.tagIds];if(name==='tags')this.editTag=undefined;},dismiss(){this.surface='';this.menu=null;this.error='';this.opener?.focus?.();},
 editDirectory(id,parent){this.editId=id;const d=this.dirs.find(d=>d.id===id);this.draftName=d?.name||'';this.draftParent=d?.parent??parent??null;this.directorySearch='';this.open(id?'move':'create');},
 openMenu(d,e){this.menu=d;const b=e.currentTarget.getBoundingClientRect();this.menuPosition='left:'+Math.min(b.right,innerWidth-180)+'px;top:'+Math.min(b.bottom+6,innerHeight-190)+'px';},directoryAction(a){const d=this.menu;this.menu=null;if(a==='新建子目录'){this.editDirectory(null,d.id);return;}this.editId=d.id;this.draftName=d.name;this.draftParent=d.parent;this.directorySearch='';this.open(({重命名:'rename',移动:'move',删除:'delete'})[a]);},blocked(id){return this.editId&&this.descendantsOf(this.editId).has(id);},
 organize(){const i=this.current();if(!i)return;this.selected=i.id;this.draftParent=i.directory;this.draftTags=[...i.tags];this.directorySearch='';this.tagSearch='';this.open('organize');},
 persist(){localStorage.setItem('agent-info-library-prototype-v6'+(new URLSearchParams(location.search).get('state')?'-'+new URLSearchParams(location.search).get('state'):''),JSON.stringify({dirs:this.dirs,tags:this.tags,items:this.items}));},
 submit(){this.error='';if(this.failNext){this.failNext=false;this.error='保存失败，输入已保留，请重试。';return;}if(['create','rename','move'].includes(this.surface)){const name=this.draftName.trim(),old=this.dirs.find(d=>d.id===this.editId);if(!name||name.length>200||(/[\\/]/.test(name)&&!(this.surface==='move'&&old?.name===name))){this.error='请输入单级目录名称，不要填写路径。';return;}if(this.dirs.some(d=>d.id!==this.editId&&d.parent===this.draftParent&&d.name.toLowerCase()===name.toLowerCase())){this.error='此位置已有同名目录。';return;}if(this.blocked(this.draftParent)){this.error='不能移动到自身或下级目录。';return;}if(old){old.name=name;old.parent=this.draftParent;this.directory=old.id;}else{const id='new-'+crypto.randomUUID();this.dirs.push({id,name,parent:this.draftParent});this.directory=id;}let parent=this.dirs.find(d=>d.id===this.directory)?.parent;while(parent){this.collapsed=this.collapsed.filter(id=>id!==parent);parent=this.dirs.find(d=>d.id===parent)?.parent;}}else if(this.surface==='delete'){if(this.count(this.editId)||this.hasChildren(this.editId)){this.error='请先移动信息和子目录。';return;}this.dirs=this.dirs.filter(d=>d.id!==this.editId);if(this.directory===this.editId)this.all();}else if(this.surface==='deleteTag'){const id=this.pendingTag.id;this.tags=this.tags.filter(t=>t.id!==id);for(const i of this.items)i.tags=i.tags.filter(t=>t!==id);this.tagIds=this.tagIds.filter(t=>t!==id);this.surface='tags';this.notice='标签已删除，信息已保留。';this.persist();return;}else if(this.surface==='filter'){this.tagIds=[...this.draftTags];this.selected=null;}else if(this.surface==='organize'){const i=this.current();i.directory=this.draftParent;i.tags=[...this.draftTags];}this.persist();this.dismiss();this.notice='已保存';},
 saveTag(){const name=this.tagNameDraft.trim();if(!name||name.length>200){this.error='请输入有效的标签名称。';return;}if(this.tags.some(t=>t.id!==this.editTag&&t.name.toLowerCase()===name.toLowerCase())){this.error='已有同名标签。';return;}if(this.editTag)this.tags.find(t=>t.id===this.editTag).name=name;else this.tags.push({id:crypto.randomUUID(),name});this.editTag=undefined;this.error='';this.persist();}
})));
